media.css:
[data-ui-unit="media"].product-media {
  margin: 0;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
}

[data-ui-unit="media"].product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 44% center;
  display: block;
}

@media (min-width: 701px) {
  [data-ui-unit="media"].product-media {
    border-radius: 8px;
  }
}

identity.css:
[data-ui-unit="identity"].product-identity {
  padding-top: 24px;
  padding-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .eyebrow {
  font-size: 14px;
  color: #60606a;
  margin-bottom: 8px;
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  color: #202024;
  margin: 0;
}

[data-ui-unit="identity"].product-identity .price-row {
  margin-top: 12px;
  margin-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .price {
  font-size: 24px;
  font-weight: 800;
  color: #202024;
}

[data-ui-unit="identity"].product-identity .metadata {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: #555560;
  line-height: 1.5;
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
  flex-shrink: 0;
}

[data-ui-unit="identity"].product-identity .description {
  margin-top: 20px;
  font-size: 15px;
  line-height: 1.75;
  color: #202024;
  margin-bottom: 0;
}

@media (min-width: 701px) {
  [data-ui-unit="identity"].product-identity {
    padding-top: 0;
  }

  [data-ui-unit="identity"].product-identity .title {
    font-size: 28px;
  }
}

booking.css:
[data-ui-unit="booking"]#booking-layout {
  border-top: 1px solid #ededf0;
  padding: 20px 0;
}

[data-ui-unit="booking"] .booking-host-title {
  margin: 0 0 4px 0;
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  line-height: 1.4;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  margin: 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.5;
}

[data-ui-unit="booking"] #booking-actions {
  padding-top: 20px;
}

[data-ui-unit="booking"] .booking-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  cursor: pointer;
  color: #60606a;
  transition: color 0.2s ease, background-color 0.2s ease;
  border-radius: 6px;
}

[data-ui-unit="booking"] .booking-icon-btn:hover {
  background-color: #f4f4f5;
  color: #202024;
}

[data-ui-unit="booking"] .booking-icon-btn:active {
  background-color: #e4e4e7;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  pointer-events: none;
}

[data-ui-unit="booking"] .booking-primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 52px;
  min-width: 0;
  padding: 0 24px;
  margin: 0;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease, opacity 0.2s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

[data-ui-unit="booking"] .booking-primary-btn:hover {
  background-color: #4338ca;
}

[data-ui-unit="booking"] .booking-primary-btn:active {
  background-color: #3b2fa6;
  opacity: 0.95;
}

[data-ui-unit="booking"] .booking-note {
  margin-top: 12px;
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
}
